@startuml

enum Unit {
  CELSIUS
  WATT
}

class SensorController {
}

class Apartment {
  + address : string
  + emailAddress : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor extends Sensor {
  + min : float
  + max : float
}

class PowerSensor extends Sensor {
  + counterReading : long
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class E_Monitor {}

SensorController "1" -- "1" Apartment
Apartment "1" -- "2..*" Room
Apartment "1" -- "*" Inhabitant
Room "1" -- "*" Sensor
Sensor "1" -- "*" MeasuredValue : has
SensorController "1" -- "*" Sensor : manages
SensorController "1" -- "1" E_Monitor : interacts with
E_Monitor "1" -- "*" Sensor : checks thresholds

@enduml

